function defaultMaxFixCyclesForDifficulty(difficulty: TaskDifficulty): number {
  switch (difficulty) {
    case "trivial":
    case "simple":
      return 1;
    case "standard":
      return 2;
    case "complex":
      return 3;
    case "critical":
      return 4;
  }
}

